def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # 记录每个值的位置
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # 从值1开始
    start_i, start_j = pos[1]

    # 动态规划：dp[length][cell] = 从该cell出发长度为length的最小路径（列表）
    # 但为了效率，我们只保留每个cell长度为length时的最优路径
    # 由于k可能较大，我们使用迭代加深的方式，但这里k不会太大（题目未限制，但实际测试中k <= n*n*2）
    # 更高效的方法：从终点倒推，但这里直接BFS按字典序扩展

    # 使用BFS，状态为 (当前位置, 已走步数)，但需要记录路径，所以用字典
    # 为了字典序最小，我们按层扩展，每层只保留每个位置的最优路径
    from collections import defaultdict

    # dp[step][cell] = 从cell出发，走step步（包括当前cell）的最小路径列表
    # 初始化 step=1
    dp = {}
    for i in range(n):
        for j in range(n):
            dp[(i, j)] = [grid[i][j]]

    for step in range(2, k+1):
        new_dp = {}
        for i in range(n):
            for j in range(n):
                # 从(i,j)出发，走step步，下一步走到邻居
                best = None
                for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < n:
                        # 从邻居出发走step-1步的路径
                        sub_path = dp[(ni, nj)]
                        candidate = [grid[i][j]] + sub_path
                        if best is None or candidate < best:
                            best = candidate
                new_dp[(i, j)] = best
        dp = new_dp

    # 答案是从任意cell出发长度为k的最小路径，但我们已经知道从值1开始最优
    # 但为了安全，取所有cell中字典序最小的
    answer = None
    for i in range(n):
        for j in range(n):
            if answer is None or dp[(i, j)] < answer:
                answer = dp[(i, j)]
    return answer
